function lightsNew(n){ n=n||5; var b=[]; for(var i=0;i<n*n;i++) b.push(0); return b; }
function lightsToggle(b, r, c, n){ n=n||5; var nb=b.slice(); var cells=[[r,c],[r-1,c],[r+1,c],[r,c-1],[r,c+1]]; cells.forEach(function(p){ var rr=p[0],cc=p[1]; if(rr>=0&&rr<n&&cc>=0&&cc<n){ nb[rr*n+cc]=nb[rr*n+cc]?0:1; } }); return nb; }
function lightsSolved(b){ return b.every(function(x){return x===0;}); }
function lightsScramble(n, steps){ n=n||5; steps=steps||8; var b=lightsNew(n); for(var s=0;s<steps;s++){ var r=Math.floor(Math.random()*n), c=Math.floor(Math.random()*n); b=lightsToggle(b,r,c,n); } return b; }
var EXPORTS={lightsNew:lightsNew,lightsToggle:lightsToggle,lightsSolved:lightsSolved,lightsScramble:lightsScramble};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LightsForgePure = EXPORTS; }
